/**
 * §4 availability: the identifiers of lists whose candidates are ALL below
 * the high-weight filter (or empty) — an exhaustive-only reviewer holding
 * ONLY the high-weight leg may pass. Called per checklist item (§4a) AND
 * over the full pool (§4b): both views must pass before the review counts
 * complete.
 */
function highWeightUnavailableOf(lists) {
    var unavailable = [];
    var input = Array.isArray(lists) ? lists : [];
